function validate(input) {
  const [{ orders = [] }] = input;
  if (!orders.length) return 'orders needs at least one row.';
  const seen = new Set(), counts = new Map();
  for (const [order, customer] of orders) {
    if (order === null) return 'Every order needs an order_number.';
    if (seen.has(order)) return `order_number ${order} appears twice.`;
    if (customer === null) return 'Every order needs a customer_number.';
    seen.add(order);
    counts.set(customer, (counts.get(customer) ?? 0) + 1);
  }
  const sorted = [...counts.values()].sort((a, b) => b - a);
  if (sorted.length > 1 && sorted[0] === sorted[1]) return 'Two customers tie for the most orders.';
  return null;
}

