function generate(rand, size) {
  const small = size === 'small';
  const others = small ? Math.floor(rand() * 4) : 300;
  const maxEach = small ? 2 : 6;
  const pool = new Set();
  while (pool.size < others + 1) pool.add(1 + Math.floor(rand() * (small ? 12 : 5000)));
  const customers = [...pool];
  const counts = customers.map(() => 1 + Math.floor(rand() * maxEach));
  // One customer (anywhere in the list) gets strictly more orders than everyone else.
  const winner = Math.floor(rand() * customers.length);
  counts[winner] = Math.max(...counts.filter((_, i) => i !== winner), 0) + 1;
  const rows = [];
  customers.forEach((customer, i) => { for (let k = 0; k < counts[i]; k++) rows.push(customer); });
  if (small) while (rows.length > 8) {
    // Drop one order from a non-winning customer that still has two or more.
    const i = rows.findIndex((c, j) => c !== customers[winner] && rows.indexOf(c) !== j);
    if (i < 0) break;
    rows.splice(i, 1);
  }
  for (let i = rows.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [rows[i], rows[j]] = [rows[j], rows[i]]; }
  return [{ orders: rows.map((customer, i) => [i + 1, customer]) }];
}
